import re

# One comprehension checkpoint per official topic, plus a concise oral-answer outline.
# These are authored practice questions, not additional questions attributed to the PDF.
TOPICS=[
('Операции с матрицами','Для AB число столбцов A должно равняться числу строк B.','Любые две матрицы можно перемножить.','Умножение матриц всегда коммутативно.',r'(AB)_{ij}=\sum_k a_{ik}b_{kj},\quad(AB)^T=B^TA^T','A размера m×n и B размера n×p дают AB размера m×p. Складываются матрицы одинакового размера. Транспонирование меняет строки и столбцы. Квадратная матрица имеет m=n; у диагональной все внедиагональные элементы нулевые.'),
('Миноры и алгебраические дополнения','Алгебраическое дополнение равно (-1)^(i+j), умноженному на минор.','Алгебраическое дополнение всегда равно минору.','При вычислении Mij удаляют только строку i.',r'A_{ij}=(-1)^{i+j}M_{ij},\quad\det A=\sum_j a_{ij}A_{ij}','Минор Mij получаем удалением строки i и столбца j. Определитель раскладывается по любой строке или столбцу. Для 2×2 det A=ad-bc. Для 3×3 можно применять разложение или правило Саррюса.'),
('Свойства определителей','Прибавление к строке другой строки с множителем не меняет определитель.','Перестановка двух строк сохраняет знак определителя.','det(AB)=det A+det B.',r'\det(AB)=\det A\det B,\quad\det A^T=\det A','Перестановка двух строк меняет знак. Общий множитель строки выносится из определителя. Прибавление кратной другой строки не меняет его. Нулевая строка или линейно зависимые строки дают нулевой определитель.'),
('Формулы Крамера','При det A ≠ 0 решение квадратной системы: xi=Δi/Δ.','Формулы Крамера применимы с тем же частным при Δ=0.','Δi получается заменой строки i на правую часть.',r'x_i=\frac{\Delta_i}{\Delta},\quad\Delta=\det A\ne0','Δi получается заменой i-го столбца A столбцом правых частей. Если Δ=0, эти формулы не дают решения; нужно исследовать ранги или применять Гаусса.'),
('Обратная матрица','Квадратная матрица обратима тогда и только тогда, когда det A ≠ 0.','Матрица обратима именно при det A=0.','A⁻¹ получается обращением каждого элемента.',r'AA^{-1}=A^{-1}A=E,\quad A^{-1}=\frac{\operatorname{adj}A}{\det A}','Присоединённая матрица - транспонированная матрица алгебраических дополнений. Другой алгоритм: (A|E) приводим к (E|A⁻¹). (AB)⁻¹=B⁻¹A⁻¹, (Aᵀ)⁻¹=(A⁻¹)ᵀ. Вырожденность означает det A=0.'),
('Матричные уравнения','Из XA=B при обратимой A следует X=BA⁻¹.','Из XA=B следует X=A⁻¹B.','Из AX=B следует X=BA⁻¹.',r'AX=B\Rightarrow X=A^{-1}B,\quad XA=B\Rightarrow X=BA^{-1}','Обратную матрицу домножаем с той стороны, где стоит коэффициент A. Из AX+B=C следует X=A⁻¹(C-B), а из XA+B=C следует X=(C-B)A⁻¹. Для AX=b решение X=A⁻¹b.'),
('Ранг и базисный минор','Ранг равен наибольшему порядку ненулевого минора.','Ранг равен числу ненулевых элементов.','При перестановке строк ранг меняется.',r'\operatorname{rank}A=\max\{k:\exists M_k\ne0\}','Элементарные преобразования сохраняют ранг. В ступенчатом виде это число ненулевых строк. Базисный минор имеет порядок r=rank A и не равен нулю. Его строки и столбцы независимы и задают базис соответствующих пространств; остальные выражаются через них.'),
('Матрицы и решения СЛАУ','Расширенная матрица образуется добавлением столбца правых частей.','Расширенная матрица получается добавлением строки правых частей.','Частное решение обязательно содержит все свободные параметры.',r'AX=b,\quad(A|b)','Матрица A содержит коэффициенты при неизвестных, X - столбец неизвестных, b - правые части. Частное решение - один подходящий набор значений. Общее решение описывает все наборы, удовлетворяющие системе.'),
('Метод Гаусса','Свободных неизвестных в совместной системе n-r.','Свободных неизвестных всегда r.','Можно изменять коэффициенты строки, не изменяя её правую часть.',r'\text{число свободных неизвестных}=n-r','Прямой ход приводит расширенную матрицу к ступенчатому виду, обратный выражает базисные неизвестные через свободные. Перестановка строк, умножение на ненулевое число и прибавление кратной другой строки сохраняют множество решений. Однородная система имеет b=0.'),
('Совместность и ФСР','Система совместна тогда и только тогда, когда rank A = rank(A|b).','Система совместна только при det A ≠ 0.','Любая однородная система имеет только нулевое решение.',r'X=X_p+\sum_{j=1}^{n-r}c_jv_j','При равных рангах r=n решение единственное, при r<n решений бесконечно много. Однородная система имеет ненулевое решение при r<n. ФСР - базис её пространства решений из n-r независимых векторов. Общее решение неоднородной системы: частное плюс общее решение однородной.'),
('Линейные операции с векторами','Координаты AB равны координатам B минус координаты A.','Координаты AB всегда равны A-B.','При умножении на отрицательное число направление сохраняется.',r'\overrightarrow{AB}=B-A,\quad a+b=b+a','Вектор характеризуется длиной и направлением. Сложение строится по правилу треугольника или параллелограмма. Умножение на λ масштабирует длину на |λ|, при λ<0 меняет направление. Линейные операции обладают распределительными и сочетательными свойствами.'),
('Координаты, проекции и базис','Для ненулевых векторов коллинеарность равносильна пропорциональности координат.','Коллинеарные векторы обязательно равны.','Проекция суммы всегда равна произведению проекций.',r'M=\frac{A+\lambda B}{1+\lambda},\quad\lambda=AM/MB>0','Базис - линейно независимая система, через которую выражается любой вектор пространства. В декартовом ортонормированном базисе координаты - проекции на оси. Проекция линейна. При внутреннем делении AM:MB=λ координаты M=(A+λB)/(1+λ).'),
('Компланарность и ориентация','Три вектора компланарны, если их смешанное произведение равно нулю.','Любые три вектора в пространстве компланарны.','Правую и левую тройки можно различить только по длинам.',r'(a,b,c)=0\iff\text{компланарны}','Компланарные векторы лежат в одной плоскости или параллельных ей плоскостях. Положительный определитель координат в правом базисе означает правую тройку, отрицательный - левую. Нулевой определитель означает отсутствие пространственной ориентации тройки.'),
('Скалярное произведение','Для ненулевых векторов a·b=0 равносильно перпендикулярности.','a·b всегда является вектором.','a·b=|a||b| sin φ.',r'a\cdot b=\sum_i a_ib_i=|a||b|\cos\varphi','Длина |a|=√(a·a). cos φ=(a·b)/(|a||b|). Скалярная проекция a на направление b равна (a·b)/|b|, векторная проекция - ((a·b)/|b|²)b. Произведение симметрично и линейно по каждому аргументу.'),
('Векторное произведение','Площадь треугольника на a,b равна |a×b|/2.','a×b=b×a для любых векторов.','a×b параллельно обоим исходным векторам.',r'a\times b=\begin{vmatrix}i&j&k\\a_x&a_y&a_z\\b_x&b_y&b_z\end{vmatrix}','Векторное произведение перпендикулярно a и b, его длина |a||b|sin φ. Направление задаёт правую тройку. a×b=-b×a. Для ненулевых векторов a×b=0 равносильно коллинеарности. Площадь параллелограмма равна модулю произведения.'),
('Смешанное произведение','Объём тетраэдра на трёх рёбрах равен |(a,b,c)|/6.','Объём тетраэдра равен смешанному произведению без модуля.','Смешанное произведение всегда является вектором.',r'(a,b,c)=(a\times b)\cdot c=\det\begin{pmatrix}a\\b\\c\end{pmatrix}','Модуль смешанного произведения равен объёму параллелепипеда. При перестановке двух аргументов знак меняется, при циклической перестановке сохраняется. Нулевое значение - критерий компланарности.'),
('Прямая на плоскости','В уравнении Ax+By+C=0 нормаль равна (A;B).','В уравнении Ax+By+C=0 направляющий вектор всегда (A;B).','Вертикальная прямая обязательно имеет вид y=kx+b.',r'Ax+By+C=0,\quad s=(-B;A),\quad n=(A;B)','Канонический вид (x-x₀)/m=(y-y₀)/n; параметрический x=x₀+mt, y=y₀+nt. Для y=kx+b параллельность: k₁=k₂, перпендикулярность: k₁k₂=-1, если оба коэффициента существуют. Уравнение в отрезках x/a+y/b=1 применимо при ненулевых отрезках.'),
('Уравнения плоскости','Для плоскости через M₀ с нормалью n: n·(r-r₀)=0.','Нормаль плоскости лежит в этой плоскости.','Параллельные нормали означают перпендикулярность плоскостей.',r'A(x-x_0)+B(y-y_0)+C(z-z_0)=0','Через три неколлинеарные точки нормаль n=AB×AC. Плоскости параллельны при коллинеарных нормалях, совпадают при пропорциональности всех четырёх коэффициентов, перпендикулярны при n₁·n₂=0. cos острого угла = |n₁·n₂|/(|n₁||n₂|).'),
('Прямая в пространстве','Направление пересечения плоскостей задаётся n₁×n₂, если нормали неколлинеарны.','Направление прямой всегда равно сумме нормалей плоскостей.','Нулевая компонента направления запрещает параметрическую запись.',r'r=r_0+ts,\quad s=B-A','Канонический вид (x-x₀)/m=(y-y₀)/n=(z-z₀)/p. При нулевой компоненте направления соответствующая координата постоянна, делить на ноль нельзя. Пересечение двух непараллельных плоскостей задаёт прямую.'),
('Расположение и расстояния между прямыми','Непараллельные прямые в пространстве могут быть скрещивающимися.','Любые непараллельные прямые в пространстве пересекаются.','Скрещивающиеся прямые лежат в одной плоскости.',r'd=\frac{|(Q-P)\cdot(s_1\times s_2)|}{|s_1\times s_2|}','При s₁×s₂≠0 прямые пересекаются тогда и только тогда, когда (Q-P)·(s₁×s₂)=0. Иначе они скрещиваются. Для параллельных d=|(Q-P)×s₁|/|s₁|. Острый угол задаётся |s₁·s₂|/(|s₁||s₂|).'),
('Прямая и плоскость','Прямая параллельна плоскости по направлению, если s·n=0.','Прямая перпендикулярна плоскости при s·n=0.','Расстояние до плоскости не требует деления на длину нормали.',r'd=\frac{|Ax_0+By_0+Cz_0+D|}{\sqrt{A^2+B^2+C^2}}','Если s·n≠0, есть единственная точка пересечения. Если s·n=0, прямая лежит в плоскости или не пересекает её; проверяют исходную точку. При коллинеарности s и n прямая перпендикулярна плоскости. sin острого угла = |s·n|/(|s||n|).'),
('Проекции и симметрия','Если H - ортогональная проекция P, то симметричная точка P*=2H-P.','Симметричная точка всегда равна самой проекции.','При проекции на прямую можно не проверять перпендикулярность.',r'H=P-\frac{n\cdot P+D}{|n|^2}n,\quad P^*=2H-P','Для прямой r=Q+ts параметр проекции t₀=((P-Q)·s)/|s|². Расстояние до прямой |(P-Q)×s|/|s|. Для параллельных плоскостей с одинаковой нормалью d=|D₂-D₁|/|n|. Перед формулой нормали приводят к одинаковым коэффициентам.'),
('Кривые второго порядка','Для гиперболы c²=a²+b² и эксцентриситет больше 1.','Для эллипса c²=a²+b².','Для параболы обязательно есть два фокуса.',r'\frac{x^2}{a^2}+\frac{y^2}{b^2}=1,\quad\frac{x^2}{a^2}-\frac{y^2}{b^2}=1,\quad y^2=4fx','У эллипса сумма расстояний до фокусов 2a, c²=a²-b² и ε<1. У гиперболы модуль разности 2a, c²=a²+b², ε>1, асимптоты y=±(b/a)x. Директрисы x=±a/ε. Парабола равноудалена от фокуса и директрисы. Сдвиги центра вводятся заменами x-h, y-k.'),
('Поверхности второго порядка','x²/a²+y²/b²-z²/c²=1 задаёт однополостный гиперболоид.','x²/a²+y²/b²+z²/c²=1 задаёт конус.','Любая поверхность без одной координаты является эллипсоидом.',r'\frac{x^2}{a^2}+\frac{y^2}{b^2}+\frac{z^2}{c^2}=1','Все три квадрата со знаком плюс и правая часть 1 - эллипсоид. Два плюса и минус при 1 - однополостный гиперболоид; один плюс и два минуса - двуполостный. Правая часть 0 при смешанных знаках - конус. Два квадрата равны линейной координате - параболоид; одинаковые знаки дают эллиптический, разные - гиперболический. Отсутствие координаты даёт цилиндр.'),
('Сечения и канонический вид','Для пересечения прямой и поверхности подставляют параметрические координаты прямой.','Для сечения y=y₀ нужно заменить x на y₀.','Выделение полного квадрата не меняет постоянную часть.',r'ax^2+bx=a\left(x+\frac b{2a}\right)^2-\frac{b^2}{4a}','Канонический вид получают выделением полных квадратов и переносом констант. Для сечения плоскостью фиксируют её координату. Для пересечения с прямой подстановка даёт уравнение относительно t, после решения каждого допустимого t восстанавливают все координаты.'),
('Алгебраическая форма комплексного числа','Для z=a+bi число Im z равно b, а не bi.','Мнимая часть a+bi равна bi.','Сопряжённое к a+bi равно -a+bi.',r'z=a+bi,\quad\overline z=a-bi,\quad z\overline z=a^2+b^2','i²=-1. Сложение и умножение выполняются с учётом этого равенства. Деление на ненулевое число - умножение числителя и знаменателя на сопряжённое знаменателя. Сопряжение сохраняет сумму и произведение, а также отношение при ненулевом знаменателе.'),
('Модуль и аргумент','В z=r(cos φ+i sin φ) модуль r=√(a²+b²).','Главный аргумент одинаков для всех четвертей при одинаковом a.','У нулевого комплексного числа есть единственный аргумент.',r'z=r(\cos\varphi+i\sin\varphi)=re^{i\varphi}','Главный аргумент выбираем в (-π;π], общий аргумент φ+2πk. Четверть определяется знаками a,b. У нуля аргумент не определён. При умножении модули перемножаются, аргументы складываются; при делении модули делятся, аргументы вычитаются.'),
('Формула Муавра и корни','Ненулевое комплексное число имеет n различных корней n-й степени.','У ненулевого числа всегда только один комплексный корень.','При возведении в степень аргумент остаётся тем же.',r'z_k=\sqrt[n]r\left[\cos\frac{\varphi+2\pi k}{n}+i\sin\frac{\varphi+2\pi k}{n}\right]','В формуле корней k=0,…,n-1. Корни расположены в вершинах правильного n-угольника. Формула Муавра: [r(cos φ+i sin φ)]ⁿ=rⁿ(cos nφ+i sin nφ). Для отрицательной целой степени число должно быть ненулевым.'),
('Многочлены и теорема Безу','Остаток от деления P(x) на x-a равен P(a).','Остаток от деления P(x) на x-a всегда равен нулю.','Если a - корень, то x+a обязательно является делителем.',r'P(x)=(x-a)Q(x)+P(a)','Корень a означает P(a)=0, то есть делимость на x-a. Кратность m - максимальная степень (x-a)^m, делящая многочлен. При делении P=DQ+R степень остатка меньше степени делителя. Сложение и умножение выполняют по коэффициентам и распределительному закону.'),
('Основная теорема алгебры','Многочлен степени n над C имеет n корней с учётом кратности.','Любой многочлен степени n имеет n различных действительных корней.','У многочлена с действительными коэффициентами комплексный корень никогда не имеет сопряжённой пары.',r'P(z)=a_n\prod_{j=1}^{n}(z-z_j)','Каждый ненулевой многочлен положительной степени имеет комплексный корень. Для действительных коэффициентов невещественные корни идут сопряжёнными парами, (x-(a+bi))(x-(a-bi))=(x-a)²+b². Поэтому над R разложение состоит из линейных и неприводимых квадратных множителей.')
]
def populate(add,steps,stage,field,fields,pages):
 official={}
 for page,text in enumerate(pages['linear-questions'],1):
  matches=list(re.finditer(r'(?m)^\s*(\d{1,2})\.\s',text))
  for i,m in enumerate(matches):
   part=text[m.end():matches[i+1].start() if i+1<len(matches) else len(text)]
   official[int(m[1])]=(page,' '.join(part.split()))
 assert set(official)==set(range(1,31))
 for n,(topic,correct,wrong1,wrong2,formula,outline) in enumerate(TOPICS,1):
  options=[correct,wrong1,wrong2];shift=(n-1)%3;options=options[shift:]+options[:shift];answer=str(options.index(correct)+1);page,text=official[n]
  task=add(f'la-oral-{n:02}',9,f'Вопрос {n}. {topic}',r'\text{Какое утверждение верно?}',answer,steps(formula,r'\text{Сначала проверяем определения и условия применимости.}',r'\text{Ответ: }'+answer,r'\text{План устного ответа}',['Формулы к этому вопросу.','Не забываем ограничения: ненулевые векторы, обратимость, совместность и область определения.','Верное утверждение: '+correct,outline]),kind='choice',file='linear-questions',page=page,label=f'Вопросы курса · №{n}',options=[dict(value=str(i+1),label=v) for i,v in enumerate(options)],description=f'Тема официального вопроса: {text}\n\nНиже - авторская проверка понимания. Полный устный ответ должен раскрывать все подпункты темы.',instruction='Выбери одно верное утверждение.')
  task['origin']='extra'
